<div class="p-info">Private legal, agreement, tax, and bank details are managed through TCM One administration and are never published in the directory.</div><section class="p-section"><h2>Public institution profile</h2><form class="p-form" method="post" action="<?= base_url('/partner/profile') ?>"><?= csrf_field() ?><label>Display name<input name="display_name" value="<?= e($ctx['partner']['display_name']) ?>" required></label><label>Website<input type="url" name="website" value="<?= e($ctx['partner']['website']??'') ?>"></label><label>Public email<input type="email" name="public_email" value="<?= e($ctx['partner']['public_email']??'') ?>"></label><label>Public phone<input name="public_phone" value="<?= e($ctx['partner']['public_phone']??'') ?>"></label><label>WhatsApp<input name="whatsapp" value="<?= e($ctx['partner']['whatsapp']??'') ?>"></label><label>City<input name="city" value="<?= e($ctx['partner']['city']??'') ?>"></label><label>State<input name="state" value="<?= e($ctx['partner']['state']??'') ?>"></label><label>Postal code<input name="postal_code" value="<?= e($ctx['partner']['postal_code']??'') ?>"></label><label class="wide">Address<textarea name="address" rows="2"><?= e($ctx['partner']['address']??'') ?></textarea></label><label class="wide">Description<textarea name="description" rows="4"><?= e($ctx['partner']['description']??'') ?></textarea></label><label class="wide">Google Maps link<input type="url" name="map_url" value="<?= e($ctx['partner']['map_url']??'') ?>"></label><div class="wide"><button class="tcm-btn primary">Submit Profile Changes</button> <span class="p-muted">Current status: <?= e(str_replace('_',' ',$ctx['partner']['public_status'])) ?></span></div></form></section>
